export function HarnessMark({
	harness,
	className = "trends-mark",
}: {
	readonly harness: TrendsHarness;
	readonly className?: string;
}) {
	const mark = HARNESS_PATHS[harness];
	return (
		<svg className={className} viewBox={mark.viewBox} aria-hidden="true">
			<path fill="currentColor" fillRule="evenodd" d={mark.d} />
		</svg>
	);
}

/** Providers without a drawn mark fall back to a lettered monogram. */
function providerGlyph(provider: TrendsProvider) {
	return provider === "xai" ? "X" : provider.charAt(0).toUpperCase();
}

export function ProviderMark({
	provider,
}: {
	readonly provider: TrendsProvider;
}) {
	const mark = PROVIDER_PATHS[provider];
	if (!mark) {
		return (
			<svg className="trends-mark" viewBox="0 0 20 20" aria-hidden="true">
				<circle cx="10" cy="10" r="9" className="trends-mark-monogram" />
				<text x="10" y="14" textAnchor="middle" fontSize="11" fontWeight="600">
					{providerGlyph(provider)}
				</text>
			</svg>
		);
	}
	return (
		<svg className="trends-mark" viewBox={mark.viewBox} aria-hidden="true">
			<path fill={mark.color ?? "currentColor"} fillRule="evenodd" d={mark.d} />
		</svg>
	);
}

/** The same mark, positioned inside an existing SVG plot. */
export function SvgProviderMark({
	provider,
	x,
	y,
	size,
}: {
	readonly provider: TrendsProvider;
	readonly x: number;
	readonly y: number;
	readonly size: number;
}) {
	const mark = PROVIDER_PATHS[provider];
	if (!mark) {
		return (
			<g className="trends-svg-mark">
				<circle
					className="trends-mark-monogram"
					cx={x + size / 2}
					cy={y + size / 2}
					r={size / 2}
				/>
				<text
					x={x + size / 2}
					y={y + size * 0.72}
					textAnchor="middle"
					fontSize={size * 0.62}
					fontWeight="600"
				>
					{providerGlyph(provider)}
				</text>
			</g>
		);
	}
	return (
		<svg
			className="trends-svg-mark"
			x={x}
			y={y}
			width={size}
			height={size}
			viewBox={mark.viewBox}
			role="presentation"
			pointerEvents="none"
		>
			<path fill={mark.color ?? "currentColor"} fillRule="evenodd" d={mark.d} />
		</svg>
	);
}

/** Rank change since the previous period: arrow plus places, never color alone. */
export function Movement({
	movement,
}: {
	readonly movement: RankMovement | undefined;
}) {
	if (!movement) return null;
	if (movement.delta === null) {
		return (
			<span className="trends-move" data-dir="new">
				{movement.isNew ? "new" : "no prior comparison"}
			</span>
		);
	}
	if (movement.delta === 0) {
		return (
			<span className="trends-move" data-dir="same">
				<span aria-hidden="true">–</span>
				<span className="visually-hidden">Unchanged rank</span>
			</span>
		);
	}
	const up = movement.delta > 0;
	const places = Math.abs(movement.delta);
	return (
		<span className="trends-move" data-dir={up ? "up" : "down"}>
			<svg viewBox="0 0 8 8" aria-hidden="true">
				<path d={up ? "M4 1.2L7.4 6.8H0.6Z" : "M4 6.8L0.6 1.2H7.4Z"} />
			</svg>
			<span aria-hidden="true">{places}</span>
			<span className="visually-hidden">
				{up ? "Up" : "Down"} {places} {places === 1 ? "place" : "places"} since
				the previous period
			</span>
		</span>
	);
}
